class LRUCache:
    """Keeps the most recently used entries, up to a capacity."""

    def __init__(self, capacity):
        self.capacity = capacity
        self._data = {}
        self._recency = []

    def _touch(self, key):
        if key in self._recency:
            self._recency.remove(key)
        self._recency.append(key)

    def recency(self):
        """Keys from least to most recently used."""
        return list(self._recency)

    def get(self, key, default=None):
        if key in self._data:
            self._touch(key)
        return self._data.get(key, default)

    def put(self, key, value):
        if key not in self._data and len(self._data) >= self.capacity:
            oldest = next(iter(self._data))
            del self._data[oldest]
            if oldest in self._recency:
                self._recency.remove(oldest)
        self._data[key] = value
        self._touch(key)

    def __contains__(self, key):
        return key in self._data

    def __len__(self):
        return len(self._data)

